export const DEMO_SONGS: SongCatalogItem[] = SONG_CATALOG;

export function getDemo(id: string): Lesson {
  const song = SONG_CATALOG.find((s) => s.id === id);
  return song ?? SONG_CATALOG[0]!;
}
